/* --- GLITZ LUXURY FOOTER & BADGES ENHANCEMENT --- */
.section-footer {
  background: #0D1C1E !important;
  color: rgba(255, 255, 255, 0.85) !important;
  border-top: 1px solid rgba(255, 255, 255, 0.08) !important;
}

.footer-institutional-header::before {
  content: "" !important;
  display: block !important;
  width: 220px !important;
  height: 52px !important;
  background-image: url('https://raw.githubusercontent.com/lian-v4/glitz-template/main/static/images/logo-glitz-header-verde.png') !important;
  background-size: contain !important;
  background-position: left center !important;
  background-repeat: no-repeat !important;
  margin-bottom: 16px !important;
  filter: brightness(0) invert(1) !important;
}

.footer-institutional-description {
  color: rgba(255, 255, 255, 0.75) !important;
  font-size: 13px !important;
  line-height: 1.6 !important;
  max-width: 320px !important;
}

.footer-menu-title {
  color: #DFCEB8 !important;
  font-weight: 700 !important;
  letter-spacing: 0.1em !important;
  text-transform: uppercase !important;
  font-size: 13px !important;
}

.footer-menu-list a {
  color: rgba(255, 255, 255, 0.7) !important;
  font-size: 13px !important;
  transition: all 0.2s ease !important;
}

.footer-menu-list a:hover {
  color: #C5A880 !important;
  transform: translateX(3px) !important;
}

.footer-payment-shipping-label {
  color: #DFCEB8 !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  letter-spacing: 0.05em !important;
  margin-bottom: 8px !important;
  display: block !important;
}

.footer-logos-wrapper {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 8px !important;
  align-items: center !important;
  margin-top: 6px !important;
  margin-bottom: 16px !important;
}

.footer-logos-wrapper .icon-logo,
.footer-payments-shipping-container img.icon-logo {
  background: #FFFFFF !important;
  padding: 4px 6px !important;
  border-radius: 5px !important;
  height: 28px !important;
  width: auto !important;
  min-width: 42px !important;
  max-width: 52px !important;
  object-fit: contain !important;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3) !important;
  display: inline-block !important;
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  transition: transform 0.2s ease !important;
}

.footer-logos-wrapper .icon-logo:hover,
.footer-payments-shipping-container img.icon-logo:hover {
  transform: translateY(-2px) !important;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.45) !important;
}



/* --- GLITZ GLOBAL CONTAINER & LATERAL PADDING --- */
.glitz-container {
  width: 100% !important;
  max-width: 1340px !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 40px !important;
  padding-right: 40px !important;
  box-sizing: border-box !important;
}

@media (max-width: 1024px) {
  .glitz-container {
    padding-left: 28px !important;
    padding-right: 28px !important;
  }
}

@media (max-width: 768px) {
  .glitz-container {
    padding-left: 20px !important;
    padding-right: 20px !important;
  }
}

.glitz-catalog-body,
.glitz-catalog-header-inner,
.glitz-catalog-container {
  width: 100% !important;
  max-width: 1340px !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 40px !important;
  padding-right: 40px !important;
  box-sizing: border-box !important;
}

@media (max-width: 1024px) {
  .glitz-catalog-body,
  .glitz-catalog-header-inner,
  .glitz-catalog-container {
    padding-left: 28px !important;
    padding-right: 28px !important;
  }
}

@media (max-width: 768px) {
  .glitz-catalog-body,
  .glitz-catalog-header-inner,
  .glitz-catalog-container {
    padding-left: 20px !important;
    padding-right: 20px !important;
  }
}

.js-product-table,
.product-grid,
.section-main-products-grid,
.section-products-slider,
.section-featured-products {
  max-width: 1340px !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 40px !important;
  padding-right: 40px !important;
  box-sizing: border-box !important;
}
